input .@megaphone$;
if (.@megaphone$ == "") end;

.@megaphone$ = replacestr(.@megaphone$, "\n", " ");

announce strcharinfo(0) + ": " + .@megaphone$, bc_all, 0x4DA6FF;

// SQL store (optional)
query_sql(
    "INSERT INTO megaphone_log (char_name, message, created_at) VALUES ('"
    + strcharinfo(0) + "', '"
    + .@megaphone$ + "', NOW())"
);

